#!/usr/bin/env python3
"""Regenerate the compact CSX-075_Q1 ground truth from local package files."""

from __future__ import annotations

import html
import json
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-075_Q1"
EVENT_ID = "CSX-075"
TARGET_FAMILY = "zhengzhou_rainfall_scale_partition_ledger"
FINAL_LABEL = "dual_scale_record_burst_and_multiday_load"

SOURCE_FILES = {
    "report": "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
    "openmeteo": "data/physical_hazard/physical_hazard_003_Open-Meteo_historical_weather_point_API.json",
    "gpm": "data/physical_hazard/physical_hazard_007_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "chirps": "data/physical_hazard/physical_hazard_009_CHIRPS_daily_event_accumulated_precipitation.json",
    "era5": "data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json",
}



REASONING_DEPTH = {'evidence_weighting': 'The reported one-hour record anchors the urban burst scale, while the point 72-hour load and gridded maxima anchor multiday accumulation scale.', 'counterfactual_rejection': 'A burst-only reading fails because the 72-hour point load exceeds the reported one-hour burst, while an accumulation-only reading misses the record-hour threshold crossing.', 'uncertainty_or_scale_caveat': 'The nearby point peak should not be used to downgrade the reported city record because the task explicitly separates point and report scales.'}


def attach_reasoning_depth(result):
    reasoning = dict(REASONING_DEPTH)
    primary = result.get("primary_gt")
    if isinstance(primary, dict):
        primary["reasoning_depth"] = reasoning
    guidance = result.get("answer_guidance")
    if isinstance(guidance, dict):
        guidance["reasoning_depth"] = reasoning
    key_values = result.get("key_values")
    if isinstance(key_values, dict):
        key_values["reasoning_depth"] = reasoning
    rubric = result.get("rubric")
    if isinstance(rubric, dict):
        criteria = rubric.get("criteria")
        if isinstance(criteria, list) and criteria:
            addition = " Full credit also requires the `reasoning_depth` object to identify decisive evidence, reject the main tempting simplification, and state a bounded uncertainty or scale caveat."
            last = criteria[-1]
            desc = last.get("description", "")
            if addition.strip() not in desc:
                last["description"] = (desc.rstrip() + addition).strip()
    return result

def task_dir() -> Path:
    return Path(__file__).resolve().parent


def package_dir() -> Path:
    return task_dir().parents[2] / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def r(value: float, digits: int) -> float:
    return round(float(value), digits)


def read_json(rel_path: str) -> Any:
    return json.loads((package_dir() / rel_path).read_text(encoding="utf-8-sig"))


def visible_text(rel_path: str) -> str:
    raw = (package_dir() / rel_path).read_text(encoding="utf-8", errors="replace")
    text = html.unescape(re.sub(r"<[^>]+>", " ", raw))
    return re.sub(r"\s+", " ", text)


def report_record_values() -> dict[str, float]:
    text = visible_text(SOURCE_FILES["report"])
    match = re.search(
        r"biggest one-hour precipitation.*?([0-9.]+)\s*mm.*?previous record was\s*([0-9.]+)\s*mm",
        text,
        flags=re.I | re.S,
    )
    if not match:
        raise ValueError("Could not extract Zhengzhou one-hour record and previous record from local report")
    return {
        "report_burst_mm": float(match.group(1)),
        "previous_record_mm": float(match.group(2)),
    }


def rolling_sum(values: list[float], window: int) -> float:
    if len(values) < window:
        raise ValueError(f"Not enough hourly values for {window}h rolling sum")
    current = sum(values[:window])
    best = current
    for idx in range(window, len(values)):
        current += values[idx] - values[idx - window]
        best = max(best, current)
    return best


def point_series_values() -> dict[str, Any]:
    payload = read_json(SOURCE_FILES["openmeteo"])
    times = payload["hourly"]["time"]
    precip = [float(value) for value in payload["hourly"]["precipitation"]]
    peak = max(precip)
    peak_idx = precip.index(peak)
    return {
        "point_hour_count": len(precip),
        "point_total_mm": sum(precip),
        "point_peak_mm": peak,
        "point_peak_time": times[peak_idx],
        "point_max24h_mm": rolling_sum(precip, 24),
        "point_max72h_mm": rolling_sum(precip, 72),
    }


def gridded_values() -> dict[str, float]:
    gpm = read_json(SOURCE_FILES["gpm"])["stats"]["gpm_event_precip_mm_max"]
    chirps = read_json(SOURCE_FILES["chirps"])["stats"]["chirps_event_precip_mm_max"]
    era5 = read_json(SOURCE_FILES["era5"])["stats"]["precipitation_sum_mm_max"]
    return {
        "gpm_max_mm": float(gpm),
        "chirps_max_mm": float(chirps),
        "era5_max_mm": float(era5),
    }


def build_answer() -> tuple[dict[str, Any], dict[str, Any]]:
    report = report_record_values()
    point = point_series_values()
    grid = gridded_values()

    report_burst_mm = report["report_burst_mm"]
    previous_record_mm = report["previous_record_mm"]
    point_total_mm = point["point_total_mm"]
    point_peak_mm = point["point_peak_mm"]
    point_max24h_mm = point["point_max24h_mm"]
    point_max72h_mm = point["point_max72h_mm"]
    gpm_max_mm = grid["gpm_max_mm"]
    chirps_max_mm = grid["chirps_max_mm"]
    era5_max_mm = grid["era5_max_mm"]
    max_spread_mm = max(grid.values()) - min(grid.values())

    answer = {
        "target_family": TARGET_FAMILY,
        "record_hour": {
            "margin_mm": r(report_burst_mm - previous_record_mm, 3),
            "ratio_to_previous_record": r(report_burst_mm / previous_record_mm, 6),
            "threshold_state": "record_hour_threshold_crossed",
        },
        "point_series_load": {
            "event_total_mm": r(point_total_mm, 1),
            "peak_hour_mm": r(point_peak_mm, 1),
            "reported_to_point_peak_ratio": r(report_burst_mm / point_peak_mm, 3),
            "max24h_mm": r(point_max24h_mm, 1),
            "max72h_mm": r(point_max72h_mm, 1),
            "max72h_fraction_of_total": r(point_max72h_mm / point_total_mm, 5),
        },
        "gridded_load": {
            "gpm_max_mm": r(gpm_max_mm, 3),
            "chirps_max_mm": r(chirps_max_mm, 3),
            "era5_max_mm": r(era5_max_mm, 3),
            "max_spread_mm": r(max_spread_mm, 3),
        },
        "partition_tests": {
            "report_burst_to_gpm_max_ratio": r(report_burst_mm / gpm_max_mm, 5),
            "max72h_to_report_burst_ratio": r(point_max72h_mm / report_burst_mm, 5),
            "final_label": FINAL_LABEL,
        },
        "rejected_substitutions": ["burst_only", "accumulation_only", "point_peak_downgrade"],
    }

    key_values = {
        "event_window": "2021-07-17 to 2021-07-23",
        **report,
        **point,
        "gpm_max_raw_mm": gpm_max_mm,
        "chirps_max_raw_mm": chirps_max_mm,
        "era5_max_raw_mm": era5_max_mm,
        "max_gridded_spread_raw_mm": max_spread_mm,
        "tolerances": {"mm": 0.05, "ratio": 0.005},
    }
    return answer, key_values


def rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Compact answer structure",
                "points": 4,
                "description": "Returns the requested compact JSON structure with target family, metric groups, final label, and rejected substitutions.",
                "partial_credit": "Up to 2 points for an incomplete JSON object; 1 point for prose with the right final label.",
            },
            {
                "name": "Record-hour threshold",
                "points": 4,
                "description": "Computes the report one-hour record minus the previous record, the record ratio, and the threshold-crossed state.",
                "partial_credit": "Up to 2 points for citing both depths with one correct derived value.",
            },
            {
                "name": "Point-series rolling load",
                "points": 4,
                "description": "Computes the point total, peak hour, reported-to-point ratio, rolling 24-hour maximum, rolling 72-hour maximum, and 72-hour fraction.",
                "partial_credit": "2-3 points for mostly correct point-series values with minor rounding or one missing window.",
            },
            {
                "name": "Gridded accumulation spread",
                "points": 3,
                "description": "Reads the three gridded event maxima and computes their maximum spread.",
                "partial_credit": "Up to 2 points if at least two gridded maxima and the large accumulation signal are correct.",
            },
            {
                "name": "Scale-partition tests",
                "points": 3,
                "description": "Computes report-burst to GPM maximum and rolling-72-hour to report-burst ratios, then gives the dual-scale final label.",
                "partial_credit": "Up to 2 points for one correct partition ratio and a broadly correct dual-scale conclusion.",
            },
            {
                "name": "Rejected substitutions",
                "points": 2,
                "description": "Rejects burst-only, accumulation-only, and point-peak-downgrade substitutions without adding uncomputed impact assertions.",
                "partial_credit": "1 point for rejecting at least two of the three substitutions.",
            },
        ],
    }


def build_ground_truth() -> dict[str, Any]:
    answer, key_values = build_answer()
    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": answer,
        "key_values": key_values,
        "rubric": rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": list(SOURCE_FILES.values()),
            "notes": "All numeric anchors are parsed or computed from local package files.",
        },
    }


def main() -> None:
    result = build_ground_truth()
    attach_reasoning_depth(result)
    (task_dir() / "computed_gt.json").write_text(
        json.dumps(result, indent=2, ensure_ascii=True, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
